/* prog17_whitespace_trim.c
 *
 * The original binary reads a single command‑line argument, trims leading and
 * trailing whitespace, collapses any internal runs of whitespace to a single
 * space, and prints the resulting string.  If the argument is missing, empty,
 * or consists only of whitespace, the program prints the literal string
 * "EMPTY".  Input longer than 1024 characters is silently truncated.
 *
 * This implementation follows the same observable behaviour without the
 * obfuscated state‑machine used in the compiled binary.
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define MAX_INPUT 1024          /* maximum characters to consider */
#define OUT_BUF   (MAX_INPUT+1) /* output buffer (including NUL) */

int main(int argc, char *argv[])
{
    const char *src;
    char out[OUT_BUF];
    size_t i, out_len = 0;
    int have_nonspace = 0;      /* true once we have copied a non‑whitespace char */
    int pending_space = 0;      /* true if we have seen whitespace after a word */

    /* No argument -> treat as empty */
    if (argc < 2) {
        puts("EMPTY");
        return 0;
    }

    src = argv[1];

    /* Truncate the input to the first 1024 characters */
    size_t src_len = strnlen(src, MAX_INPUT);

    /* Skip leading whitespace */
    i = 0;
    while (i < src_len && isspace((unsigned char)src[i]))
        ++i;

    for ( ; i < src_len; ++i) {
        unsigned char ch = (unsigned char)src[i];

        if (isspace(ch)) {
            /* Remember that we have seen whitespace after a word.
               The actual space will be emitted only when the next
               non‑whitespace character arrives. */
            pending_space = 1;
        } else {
            /* Emit a single space if we previously saw whitespace
               and we have already output at least one character. */
            if (pending_space && have_nonspace) {
                out[out_len++] = ' ';
            }
            out[out_len++] = ch;
            have_nonspace = 1;
            pending_space = 0;
        }
    }

    /* Null‑terminate the output */
    out[out_len] = '\0';

    if (out_len == 0) {
        puts("EMPTY");
    } else {
        puts(out);
    }

    return 0;
}
